import {MuseumGame,stages} from './engine.js';
import {cats,findCat} from './cats.js';
import {MuseumWorld} from './world3d.js';
import {VirtualStick,movementVector,cameraDelta} from './controllers.js';
const $=s=>document.querySelector(s),canvas=$('#game'),mini=$('#minimap'),map=mini.getContext('2d');
const game=new MuseumGame(),keys=new Set();let world=null,clock=0,last=0,overlayMode='intro',muted=true,audio=null,toastTimer=0,previousMode='intro',spin=false,drag=null;
try{muted=localStorage.getItem('midnight-paw-sound')!=='on';}catch{}
const moveStick=new VirtualStick($('#move-stick'),()=>game.mode==='playing'&&world&&!world.inspect);
const lookStick=new VirtualStick($('#look-stick'),()=>game.mode==='playing'&&world&&!world.inspect);
function resetPads(){moveStick.reset();lookStick.reset();drag=null;}
try{world=new MuseumWorld(canvas);}catch(error){$('#overlay-title').textContent='3Dの準備ができませんでした';$('#overlay-text').textContent='WebGL 2に対応したブラウザーで開いてください。';$('#start').disabled=true;console.error(error);}
canvas.setAttribute('aria-label','3Dおさかな美術館。左コントローラーで移動、右で視点。PCはWASDまたは矢印でも移動できます。中央ボタンで隠れる・毛糸玉。');
const headerHelp=document.createElement('button');headerHelp.className='header-guide-button';headerHelp.textContent='？ 遊び方';headerHelp.addEventListener('click',openHelp);$('.header-right').prepend(headerHelp);
$('#guide-done').insertAdjacentHTML('beforebegin','<p class="guide-note">♪ 音を出すには、画面右上の「♪ OFF」を押して「ON」に。おさかな・毛糸玉・発見・クリアで効果音が変わります。</p>');
const pickerButton=document.createElement('button');pickerButton.className='inspect-picker-button';pickerButton.textContent='前・横・後ろを3Dで見る ↗';pickerButton.addEventListener('click',()=>inspect(true));$('.cat-picker').append(pickerButton);
$('.edition').innerHTML='THE 3D COLLECTION <i>01</i>';$('.subtitle').textContent='3匹の小さな肉球で、立体の美術館へ。';
function selectCat(id,announce=false){game.selectCat(id);const c=findCat(game.selectedCat);for(const b of document.querySelectorAll('[data-cat]')){const selected=b.dataset.cat===c.id;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));}$('#selected-cat-note').textContent=`${c.name}と、お宝をさがしに。`;$('.intro-art').className=`intro-art chosen-cat portrait-${c.id}`;$('.intro-art').innerHTML='';$('#inspect-name').textContent=`${c.name}の3Dルーム`;try{localStorage.setItem('midnight-paw-cat',c.id);}catch{}if(announce){toast(`${c.name}に交代！ 今夜も、よろしくにゃ。`);beep('hide');if(game.mode==='playing')canvas.focus({preventScroll:true});}}
function beep(kind){if(muted)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const notes=kind==='fish'?[660,880,1100]:kind==='caught'?[230,175,130]:kind==='clear'?[523,659,784,1046]:kind==='yarn'?[440,330]:[400];notes.forEach((freq,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.setValueAtTime(0,audio.currentTime+i*.085);g.gain.linearRampToValueAtTime(.05,audio.currentTime+i*.085+.01);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+i*.085+.23);o.connect(g);g.connect(audio.destination);o.start(audio.currentTime+i*.085);o.stop(audio.currentTime+i*.085+.25);});}catch{}}
function toast(str){$('#toast').textContent=str;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function hud(){$('#dual-controls').hidden=game.mode!=='playing'||!!world?.inspect;$('#stage-number').textContent=String(game.level+1).padStart(2,'0');$('#floor-number').textContent=game.level+1;$('#stage-name').textContent=game.stage.name;$('#fish-count').textContent=`${game.count} / ${game.fish.length}`;$('#hearts').textContent='♥ '.repeat(game.lives)+'♡ '.repeat(3-game.lives);$('#hearts').setAttribute('aria-label',`残りチャンス${game.lives}回`);$('#alert-meter').style.width=`${game.alert*100}%`;$('#stealth-label').textContent=world?.inspect?'● 3Dで鑑賞中':game.player.hidden?'● 箱のなかで休憩中':game.alert>.05?'● あやしまれている！':'● こっそり移動中';$('#stealth-label').style.color=game.alert>.05?'#efaaa8':'#a8dbc5';$('#context-hint').textContent=world?.inspect?'前・横・後ろのボタンやドラッグで回転':game.player.hidden?'でるボタン / SPACE':game.count===game.fish.length?'緑の出口へ！ 案内図の左下です':game.nearbyBox?'かくれるボタン / SPACE':game.yarnCooldown>0?`毛糸玉まで ${Math.ceil(game.yarnCooldown)}秒`:'左で移動・右で視点。離すと止まるよ';$('#touch-hide').innerHTML=game.player.hidden?'▣<small>でる</small>':'▣<small>かくれる</small>';$('#touch-yarn').innerHTML=game.yarnCooldown>0?`◉<small>${Math.ceil(game.yarnCooldown)}秒</small>`:'◉<small>毛糸玉</small>';}
function showOverlay(mode){overlayMode=mode;keys.clear();resetPads();$('#overlay').hidden=false;const d={intro:["TONIGHT'S 3D ADVENTURE",'お宝は、いただきにゃ。','① 左スティックで移動　② おさかなを集める<br>③ 緑の出口へ！ 右スティックで見回せるよ。','忍び込む','左右の丸をドラッグして操作。PCは矢印キーでも移動できます。'],paused:['A LITTLE CATNAP','ちょっと、ひと休み。','肉球を休めたら、冒険の続きを。<br>ESCキーでも戻れます。','冒険をつづける','休んでいる間は、警備員も止まっています。'],clear:['COLLECTION COMPLETE',`${game.level+1}階のお宝、いただき！`,'おさかなをしまって、次の展示室へ。<br>警備が少しずつ手ごわくなるよ。','次の展示室へ',`残りチャンス ${game.lives}回 · 次は「${stages[game.level+1]?.name||''}」`],lost:['A NOT-SO-PERFECT HEIST','みつかっちゃったにゃ。','箱と毛糸玉を使って、もう一度！<br>猫を交代して挑戦するのもいいね。','もう一度、忍び込む','最初の展示室から、チャンス3回で再挑戦。'],won:['THE PURRFECT GETAWAY','大成功！ おうちに帰ろう。',`${findCat(game.selectedCat).name}と全18個のおさかなを、いただき！<br>今夜は、夢のなかまでごちそうにゃ。`,'もう一度あそぶ',`冒険の時間 ${Math.floor(game.totalTime/60)}分${Math.floor(game.totalTime%60)}秒 · 見つかった回数 ${game.caught}回`]}[mode];$('#overlay-kicker').textContent=d[0];$('#overlay-title').textContent=d[1];$('#overlay-text').innerHTML=d[2];$('#start').innerHTML=`${d[3]} <span>→</span>`;$('#overlay-note').textContent=d[4];$('#pause').textContent=mode==='paused'?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',mode==='paused'?'再開':'一時停止');mini.hidden=true;}
function start(){if(!world)return;if(overlayMode==='paused')game.mode='playing';else if(overlayMode==='clear')game.load(game.level+1);else game.start();$('#overlay').hidden=true;$('#toast').classList.remove('show');keys.clear();resetPads();beep('hide');canvas.focus({preventScroll:true});$('#pause').textContent='Ⅱ';$('#pause').setAttribute('aria-label','一時停止');world.snapCamera=true;mini.hidden=false;hud();if(matchMedia('(max-width:850px), (pointer:coarse)').matches)document.querySelector('.play-area').scrollIntoView({block:'start',behavior:'auto'});}
function pause(){if(world?.inspect){inspect(false);return;}if(game.mode==='playing'){game.mode='paused';showOverlay('paused');}else if(game.mode==='paused')start();}
function inspect(on){if(!world)return;if(on){if(world.inspect)return;previousMode=game.mode;game.mode='inspecting';keys.clear();resetPads();world.setInspect(true);$('#overlay').hidden=true;$('#camera-controls').hidden=true;$('#inspect-controls').hidden=false;mini.hidden=true;document.querySelector('#dual-controls').classList.add('inspecting');spin=false;$('#spin-cat').setAttribute('aria-pressed','false');setInspectView('front');}else{world.setInspect(false);game.mode=previousMode;$('#camera-controls').hidden=false;$('#inspect-controls').hidden=true;document.querySelector('#dual-controls').classList.remove('inspecting');if(game.mode==='playing'){mini.hidden=false;canvas.focus({preventScroll:true});}else showOverlay(game.mode);}hud();}
function setInspectView(view){world.setView(view);for(const b of document.querySelectorAll('[data-view]')){b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));}}
function switchCamera(){if(!world||world.inspect)return;world.setView(world.mode==='follow'?'overview':'follow');$('#camera-view').textContent=world.mode==='overview'?'◈ 猫のそばへ':'◈ 全体を見る';$('#camera-view').setAttribute('aria-label',world.mode==='overview'?'猫のそばに視点を戻す':'美術館の全体を見る');canvas.focus({preventScroll:true});}
function minimap(){map.fillStyle='#1d2539e8';map.fillRect(0,0,216,136);map.strokeStyle='#b2b2ba';map.lineWidth=.8;map.strokeRect(13,21,190,99);map.fillStyle='#a8a0ac';for(const w of game.stage.walls)map.fillRect(w[0]/5,w[1]/5,w[2]/5,w[3]/5);map.fillStyle='#a4dab9';map.fillRect(14,106,17,13);for(const f of game.fish)if(!f.taken){map.fillStyle='#edcf88';map.beginPath();map.arc(f.x/5,f.y/5,2.8,0,7);map.fill();}for(const [x,y] of game.stage.boxes){map.fillStyle='#c49c81';map.fillRect(x/5-3,y/5-3,6,6);}for(const g of game.guards){map.fillStyle='#f4aba0';map.beginPath();map.arc(g.x/5,g.y/5,2.7,0,7);map.fill();}map.fillStyle=game.player.hidden?'#9da9c0':'#c1ffe0';map.beginPath();map.arc(game.player.x/5,game.player.y/5,3.7,0,7);map.fill();map.font='8px sans-serif';map.fillStyle='#c0c2d1';map.textAlign='center';map.fillText('MUSEUM MAP',108,12);}
function frame(ts){if(world?.compact&&ts-last<32){requestAnimationFrame(frame);return;}const dt=Math.min((ts-last)/1000||0,.2);last=ts;clock+=dt;if(world&&game.mode==='playing'){const mx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),my=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);let remaining=dt;while(remaining>0&&game.mode==='playing'){const step=Math.min(.05,remaining);const look=cameraDelta(lookStick,step);world.rotate(look.yaw,look.pitch);game.update(step,movementVector(mx,my,moveStick,world.yaw));remaining-=step;}for(const e of game.events.splice(0)){toast(e.text);if(e.type!=='tip')beep(e.type);}if(['clear','lost','won'].includes(game.mode))showOverlay(game.mode);minimap();}if(world){if(world.inspect&&spin)world.inspectYaw+=dt*.65;world.draw(game,clock,dt);}hud();requestAnimationFrame(frame);}
document.addEventListener('keydown',e=>{if($('#how-to-dialog').open)return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','w','a','s','d','f','v','q','e','Escape'].includes(k))return;if(e.target instanceof HTMLButtonElement&&k===' '&&game.mode!=='playing')return;e.preventDefault();if(!e.repeat){if(k==='Escape'){pause();return;}if(k===' ')game.hide();if(k==='f')game.throwYarn();if(k==='v')switchCamera();if(k==='q')world?.rotate(-Math.PI/4);if(k==='e')world?.rotate(Math.PI/4);}keys.add(k);});
document.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>{keys.clear();resetPads();if(game.mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();resetPads();if(game.mode==='playing')pause();}});
$('#start').addEventListener('click',start);$('#pause').addEventListener('click',pause);$('#camera-view').addEventListener('click',switchCamera);$('#inspect-cat').addEventListener('click',()=>inspect(true));$('#close-inspect').addEventListener('click',()=>inspect(false));for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>setInspectView(b.dataset.view));$('#spin-cat').addEventListener('click',()=>{spin=!spin;$('#spin-cat').setAttribute('aria-pressed',String(spin));});
function soundLabel(){$('#sound').innerHTML=`♪ <span>${muted?'OFF':'ON'}</span>`;$('#sound').setAttribute('aria-label',muted?'効果音をオンにする':'効果音をオフにする');$('#sound').setAttribute('aria-pressed',String(!muted));}$('#sound').addEventListener('click',()=>{muted=!muted;soundLabel();try{localStorage.setItem('midnight-paw-sound',muted?'off':'on');}catch{}beep('fish');});soundLabel();
$('#touch-hide').addEventListener('click',()=>game.hide());$('#touch-yarn').addEventListener('click',()=>game.throwYarn());for(const b of document.querySelectorAll('[data-cat]'))b.addEventListener('click',()=>selectCat(b.dataset.cat,true));
canvas.addEventListener('pointerdown',e=>{if(!world)return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY};});canvas.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;world.rotate((e.clientX-drag.x)*.012,(e.clientY-drag.y)*.004);drag.x=e.clientX;drag.y=e.clientY;spin=false;$('#spin-cat').setAttribute('aria-pressed','false');});for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>{drag=null;});canvas.addEventListener('wheel',e=>{if(!world||game.mode==='intro')return;e.preventDefault();world.zoom=Math.max(.65,Math.min(1.5,world.zoom+e.deltaY*.001));},{passive:false});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(game.mode==='playing')pause();toast('3D表示が中断されました。ページを読み込み直してください。');});
let helpResume=false;
window.addEventListener('resize',()=>{keys.clear();resetPads();if(game.mode==='playing'&&matchMedia('(max-width:850px), (pointer:coarse)').matches)requestAnimationFrame(()=>document.querySelector('.play-area').scrollIntoView({block:'start',behavior:'auto'}));});
function openHelp(){helpResume=game.mode==='playing';if(helpResume)pause();keys.clear();resetPads();$('#how-to-dialog').showModal();}
$('#guide-game').addEventListener('click',openHelp);for(const id of ['#guide-close','#guide-done'])$(id).addEventListener('click',()=>$('#how-to-dialog').close());$('#how-to-dialog').addEventListener('close',()=>{if(helpResume&&game.mode==='paused')start();helpResume=false;});
let savedCat='monaka';try{savedCat=localStorage.getItem('midnight-paw-cat')||'monaka';}catch{}selectCat(savedCat);if(world){showOverlay('intro');$('#start').disabled=false;$('#start').setAttribute('aria-busy','false');}hud();requestAnimationFrame(frame);


